(function () {
    if (document.readyState !== 'complete' || !window.ReadParams) return null;
    var area = document.querySelector('#acontent');
    if (!area) return null;
    function escape(text) {
        return text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
    }
    function visible(node) {
        var rect = node.getBoundingClientRect(), style = getComputedStyle(node);
        return (node.tagName === 'IMG' || rect.width > 0) && style.display !== 'none' && style.visibility !== 'hidden' && style.opacity !== '0';
    }
    function image(node) {
        var url = node.getAttribute('data-src') || node.getAttribute('src');
        return url ? '<img src="' + escape(new URL(url, location.href).href) + '">' : '';
    }
    var parts = Array.from(area.children).filter(visible).map(function (node) {
        if (node.tagName === 'IMG') return image(node);
        if (node.tagName !== 'P') return '';
        var text = node.innerText.trim();
        return (text ? '<p>' + escape(text) + '</p>' : '') + Array.from(node.querySelectorAll('img')).map(image).join('');
    }).join('');
    if (/抱歉，您的浏览器|请使用〔Chrome/.test(area.innerText)) parts = '';
    var next = new URL(ReadParams.url_next, location.href);
    function chapter(path) { return path.replace(/_\d+(?=\.html$)/, ''); }
    var link = next.origin === location.origin && next.pathname !== location.pathname && chapter(next.pathname) === chapter(location.pathname)
        ? '<a id="next-page" href="' + escape(next.href) + '"></a>' : '';
    return '<div id="chapter">' + parts + '</div>' + link;
})()
